const bodyRaw = (analysis.body && analysis.body.persuasion_score) || 8.0;
const ctaRaw = (analysis.cta && analysis.cta.clarity_score) || 8.0;
const formatRaw = (analysis.creative_critique && analysis.creative_critique.format_score) || 8.0;

const days = ad.days_active || 10;
let longevityScore = 6.0;
if (days >= 60) longevityScore = 10.0;
else if (days >= 40) longevityScore = 9.2;
else if (days >= 20) longevityScore = 8.0;
else if (days >= 10) longevityScore = 7.0;

const hookWeighted = +(hookRaw * 3.0).toFixed(1);
const bodyWeighted = +(bodyRaw * 2.5).toFixed(1);
const ctaWeighted = +(ctaRaw * 2.0).toFixed(1);
const formatWeighted = +(formatRaw * 1.0).toFixed(1);
const longevityWeighted = +(longevityScore * 1.5).toFixed(1);

const totalCompositeScore = +(hookWeighted + bodyWeighted + ctaWeighted + formatWeighted + longevityWeighted).toFixed(1);

