}

// Safe fallback to 'Score Ad & Deconstruct' node if input is empty
if (allAds.length === 0 || !allAds[0].scores) {
  try {
    allAds = $('Score Ad & Deconstruct').all().map(item => item.json);
  } catch (err) {
    // keep current allAds
  }
}

// Safe sorting by composite_total
allAds.sort((a, b) => {
  const scoreA = (a && a.scores && typeof a.scores.composite_total === 'number') ? a.scores.composite_total : ((a && a.composite_total) || 0);
  const scoreB = (b && b.scores && typeof b.scores.composite_total === 'number') ? b.scores.composite_total : ((b && b.composite_total) || 0);
  return scoreB - scoreA;
});

// Assign definitive ranking
